// Metric, rectilinear level-design geometry. x east, y south, z up.
function buildGeometry(plan){
const zDefault={L1:4.2,L0:0,B1:-4.5,B2:-9},result={schema:'kern-blockout-2',units:'metres',axes:{x:'east',y:'south',z:'up'},sourcePlan:plan,levels:{},verticalConnections:[],courtyard:plan.courtyard||null};
for(const [id,f]of Object.entries(plan.floors)){
const z=f.z??zDefault[id],height=id==='L1'?3.9:id==='L0'?3.9:4.2,edges=new Map(),openings=[];
const rect=r=>[[r.x,r.y],[r.x+r.w,r.y],[r.x+r.w,r.y+r.h],[r.x,r.y+r.h]];
for(const r of f.rooms){if(['void','courtyard','terrace'].includes(r.type))continue;for(const [axis,fixed,lo,hi]of [['h',r.y,r.x,r.x+r.w],['h',r.y+r.h,r.x,r.x+r.w],['v',r.x,r.y,r.y+r.h],['v',r.x+r.w,r.y,r.y+r.h]]){const k=axis+':'+fixed;const e=edges.get(k)||{axis,fixed,ranges:[]};e.ranges.push({lo,hi,room:r.id,height:r.height||height});edges.set(k,e)}}
for(const d of f.doors){const g=doorGeometry(d,f);if(g)openings.push({id:d.id,a:d.a,b:d.b,axis:g.axis,fixed:g.fixed,start:g.start,end:g.end,width:d.width,z,height:2.4,sealed:!!d.sealed,type:'door'})}
for(const e of (f.externals||[f.external].filter(Boolean))){const r=f.rooms.find(r=>r.id===e.room);if(!r)continue;const vertical=['e','w'].includes(e.side),fixed=vertical?(e.side==='e'?r.x+r.w:r.x):(e.side==='s'?r.y+r.h:r.y),mid=vertical?r.y+r.h/2:r.x+r.w/2;openings.push({id:'outside-'+e.room,a:e.room,b:'outside',axis:vertical?'v':'h',fixed,start:mid-e.width/2,end:mid+e.width/2,width:e.width,z,height:e.width>=4?3.8:2.4,type:e.width>=4?'vehicle':'exterior',label:e.label})}
const walls=[];for(const e of edges.values()){const cuts=openings.filter(o=>o.axis===e.axis&&o.fixed===e.fixed),points=[...new Set([...e.ranges.flatMap(r=>[r.lo,r.hi]),...cuts.flatMap(o=>[o.start,o.end])])].sort((a,b)=>a-b);for(let i=0;i<points.length-1;i++){const lo=points[i],hi=points[i+1],mid=(lo+hi)/2,owners=e.ranges.filter(r=>mid>r.lo&&mid<r.hi);if(!owners.length)continue;const door=cuts.find(o=>mid>o.start&&mid<o.end),top=Math.max(...owners.map(r=>r.height));const [a,b]=e.axis==='h'?[[lo,e.fixed],[hi,e.fixed]]:[[e.fixed,lo],[e.fixed,hi]];walls.push({id:id+'-wall-'+walls.length,a,b,z:z+(door?door.height:0),height:top-(door?door.height:0),thickness:owners.length>1?.25:.4,rooms:owners.map(o=>o.room),kind:door?'lintel':'wall',opening:door?.id||null})}}
// The south Control edge is a low guard at L1, not a blind two-storey wall.
if(['v2','v3'].includes(plan.variant))for(const w of walls){if(w.a[1]===22&&w.b[1]===22&&w.a[0]>=32&&w.b[0]<=46&&['L0','L1'].includes(id)){w.height=Math.min(w.height,5.3-w.z);if(id==='L1')w.kind='guardwall';w.note='Open overlook above 1.1 m guard at L1'}}
const holes=f.rooms.filter(r=>r.type==='void').map(r=>({id:r.id,polygon:rect(r),reason:r.courtyardVoid?'open-sky courtyard':'double-height Control'}));
result.levels[id]={z,clearHeight:height,slabThickness:.3,rooms:f.rooms.map(r=>({...r,z:r.z??z,height:r.height||height,polygon:rect(r)})),wallSegments:walls,doorOpenings:openings,floorSlabs:f.rooms.filter(r=>!['void','courtyard'].includes(r.type)).map(r=>({room:r.id,z:z-.3,thickness:.3,polygon:rect(r),holes:holes.map(h=>h.polygon)})),floorHoles:holes,roofHoles:[...(plan.courtyard?[{id:'courtyard',polygon:rect(plan.courtyard),reason:'no covering at any height above L0'}]:[])],roofCandidates:f.rooms.filter(r=>!['void','courtyard','terrace'].includes(r.type)).map(r=>({room:r.id,z:z+(r.height||height),thickness:.3,polygon:rect(r),rule:'Omit portions covered by higher occupied volumes; courtyard always excluded'})),outdoorSpaces:f.rooms.filter(r=>r.outdoor),caveEnvelopes:f.rooms.filter(r=>r.type==='cave').map(r=>({id:r.id,polygon:rect(r),note:'Rectangular walkable envelope; irregular cosmetic cave skin must not obstruct openings'}))};}
for(const c of plan.verticalConnections||[]){const levels=c.floors;for(let i=0;i<levels.length-1;i++){const from=levels[i],to=levels[i+1],z0=result.levels[from].z,z1=result.levels[to].z,rise=z1-z0;result.verticalConnections.push({...c,id:c.id+'-'+from+'-'+to,from,to,z0,z1,rise,stair:c.type==='stair'?{type:'dogleg',flights:2,risersPerFlight:Math.ceil(rise/.18/2),riserHeight:rise/(Math.ceil(rise/.18/2)*2),treadDepth:.27,flightWidth:1.35,landingDepth:1.35,entranceSide:c.id==='clean-stair'?'east':'south',landingWidth:'full footprint width',orientation:c.id==='clean-stair'?'east-west':'north-south',floorOpening:c.footprint}:null})}}
result.approaches=[{id:'vehicle-ramp',level:'B1',type:'vehicle',width:5,start:[-28,32,0],end:[0,32,-4.5],note:'Separate west approach; 28 m run, 4.5 m descent. Gameplay slope, not vehicle-code certification.'},{id:'pedestrian-path',level:'L0',type:'outdoor network',width:2,points:[[56,25,0],[56,12.5,0],[56,-2,0],[12,-2,0],[12,2,0]],branches:[[[56,25,0],[52,25,0]],[[56,12.5,0],[54,12.5,0]]]}];return result;
}
